#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> half1, half2;
    long long max_mod_sum = 0;

    int size_half1 = 1 << ((n / 2) + (n % 2));
    for (int i = 0; i < size_half1; ++i) {
        long long sum_part = 0;
        int bit_mask = i;
        for (int j = 0; j < 20; ++j) {
            if (bit_mask & 1) {
                sum_part += a[j];
            }
            bit_mask >>= 1;
        }
        half1.push_back((int)(sum_part % m));
    }
    std::sort(half1.begin(), half1.end());

    int size_half2 = 1 << (n / 2);
    for (int i = 0; i < size_half2; ++i) {
        long long sum_part = 0;
        int bit_mask = i;
        for (int j = 0; j < 20; ++j) {
            if (bit_mask & 1) {
                sum_part += a[(n / 2) + (n % 2) + j];
            }
            bit_mask >>= 1;
        }
        sum_part %= m;

        int idx = (int)(std::lower_bound(half1.begin(), half1.end(), m - sum_part - 1) - half1.begin());

        int candidate;
        if (idx < (int)half1.size()) {
            candidate = half1[idx];
            if (candidate > m - sum_part - 1 && idx - 1 >= 0) {
                candidate = half1[idx - 1];
            }
        } else {
            candidate = half1.back();
        }

        max_mod_sum = max(max_mod_sum, (sum_part + candidate) % m);
        max_mod_sum = max(max_mod_sum, (sum_part + half1.back()) % m);
    }

    cout << max_mod_sum << "\n";

    return 0;
}
